#define MAX_W 1100

struct status {
    int x, y, step, n;
};

int dx[4] = {1, 0, -1, 0};
int dy[4] = {0, 1, 0, -1};

int H, W, N;
std::array<std::array<int, MAX_W>, MAX_H> flag = {};
char maze[MAX_H][MAX_W];
int xs, ys;
std::deque<status> Q;

int BFS();

int main() {
    while (scanf("%d%d%d", &H, &W, &N) == 3) {
        for (int i = 0; i < H; i++) {
            scanf("%s", maze[i]);
        }
        for (int j = 0; j < H; j++) {
            for (int i = 0; i < W; i++) {
                if (maze[j][i] == 'S') {
                    xs = i;
                    ys = j;
                    break;
                }
            }
        }
        printf("%d\n", BFS());
    }
}

int BFS() {
    Q.clear();
    Q.push_back({xs, ys, 0, 1});
    while (!Q.empty()) {
        status tmp = Q.front(); Q.pop_front();
        for (int i = 0; i < 4; i++) {
            int cx = tmp.x + dx[i], cy = tmp.y + dy[i];
            if (cx < 0 || cx >= W || cy < 0 || cy >= H || maze[cy][cx] == 'X') continue;

            int cn = (maze[cy][cx] - '0' == tmp.n) ? tmp.n + 1 : tmp.n;
            if (cn == N + 1) return tmp.step + 1;
            if (flag[cy][cx] >= cn) continue;

            flag[cy][cx] = cn;
            Q.push_back({cx, cy, tmp.step + 1, cn});
        }
    }
    return -1;
}

